const express = require('express');
const { createYoga, createSchema } = require('graphql-yoga');
const { GraphQLError } = require('graphql');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();

const typeDefs = `
  type ContractAgreement @key(fields: "documentKey") {
    documentKey: ID!
    title: String!
    counterpartyName: String!
    liabilityCapUsd: Float!
    ndaClauseText: String!
    status: String!
  }

  type Query {
    serviceStatus: String
  }
`;

const resolvers = {
  ContractAgreement: {
    __resolveReference: async ({ documentKey }, ctx) => {
      if (!ctx.clientOrgId) {
        throw new GraphQLError('Organization identification required', {
          extensions: { code: 'UNAUTHENTICATED' }
        });
      }

      // Restrict lookup to contracts where the organization is either the owner or counterparty
      const contract = await ctx.prisma.contractAgreement.findFirst({
        where: {
          documentKey,
          OR: [
            { ownerOrgId: ctx.clientOrgId },
            { counterpartyOrgId: ctx.clientOrgId }
          ]
        }
      });

      if (!contract) {
        throw new GraphQLError('Contract agreement not found or access unauthorized', {
          extensions: { code: 'FORBIDDEN' }
        });
      }

      return contract;
    }
  }
};

const yoga = createYoga({
  schema: createSchema({ typeDefs, resolvers }),
  context: ({ req }) => ({
    prisma,
    clientOrgId: req.headers['x-org-id']
  })
});

app.use('/subgraph/legal', yoga);
app.listen(8081);
